```python
import asyncio

from fastmcp import Client, FastMCP

mcp = FastMCP("ConfigServer")


@mcp.resource("data://config")
def get_config() -> dict:
    return {"key": "value", "debug": True}


async def main() -> None:
    # Passing the FastMCP server object directly to Client uses the
    # in-memory transport: no subprocess, no network socket.
    client = Client(mcp)

    async with client:
        contents = await client.read_resource("data://config")
        for content in contents:
            if hasattr(content, "text"):
                print(content.text)
            else:
                print(content)


if __name__ == "__main__":
    asyncio.run(main())
